// Fixes the sites copied in from the onlinetrainingcourses generator (their pages say "generated by
// scripts/generate.mjs"). They were built for *.onlinetrainingcourses.us, a domain that doesn't exist,
// so every canonical, og:url, sitemap and JSON-LD URL pointed at nothing. This rewrites them to the
// hazwoperosha.us subdomain each one is served from, and gives them what the course sites get from
// tools/build.mjs: full Organization JSON-LD, about/contact/privacy pages, a sitemap with <lastmod>,
// agent hints in llms.txt and the head. It's safe to run again, and again after a fresh import.
//
// Left alone on purpose: js/config.js and js/checkout.js (the checkout and its ORDER_FROM, see the README).
// Removed: the pages' own Google Analytics tag. The Worker adds the hub's tag to every page.
import { readdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { esc } from "./lib.mjs";
import { DOMAIN, ORG, ORG_ID, infoTitle, fitDescription, lastmods, sitemapXml, text, PHONE, EMAIL } from "./seo.mjs";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const sitesDir = join(root, "sites");
const MARK = "generated by scripts/generate.mjs";
const OLD = "onlinetrainingcourses.us";
const CATALOG = "https://hazwoper-osha.com/online-courses";

const names = readdirSync(sitesDir).filter((n) => !existsSync(join(root, "content", n))
  && existsSync(join(sitesDir, n, "index.html")) && readFileSync(join(sitesDir, n, "index.html"), "utf8").includes(MARK));
const dates = lastmods(join(root, "content/lastmod.json"));
const hosts = new Set();
for (const name of names) fixSite(name);
dates.save(hosts);
console.log(`imported: fixed ${names.length} sites`);

function fixSite(name) {
  const dir = join(sitesDir, name);
  const host = `${name}.${DOMAIN}`;
  const base = `https://${host}`;
  hosts.add(host);
  const rewrite = (s) => s
    .replaceAll(`https://www.${OLD}/assets/`, `${base}/assets/`)
    .replaceAll(`https://www.${OLD}/courses/`, CATALOG)
    .replace(new RegExp(`https://www\\.${OLD.replace(".", "\\.")}/?`, "g"), CATALOG)
    .replace(new RegExp(`https://([a-z0-9-]+)\\.${OLD.replace(".", "\\.")}`, "g"), `https://$1.${DOMAIN}`);

  for (const f of ["robots.txt", "llms.txt"]) edit(join(dir, f), rewrite);

  const index = edit(join(dir, "index.html"), (s) => headHints(footer(enrichLd(noGa(rewrite(s)), base)), "/index.md"));
  edit(join(dir, "404.html"), (s) => footer(noGa(rewrite(s))));
  edit(join(dir, "checkout.html"), (s) => footer(noGa(rewrite(s))));

  // Facts for the new pages, read from the home page.
  const topic = decode((index.match(/<title>([^<]*)<\/title>/) || [])[1] || name);
  const ld = JSON.parse((index.match(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/) || [])[1] || "{}");
  const list = (ld["@graph"] || []).find((n) => n["@type"] === "ItemList");
  const courses = (list?.itemListElement || []).map((e) => e.item).filter(Boolean).map((c) => ({
    name: c.name, url: new URL(c.url).pathname + new URL(c.url).hash, price: Number(c.offers?.[0]?.price || c.offers?.price || 0),
    duration: hours(c.hasCourseInstance?.[0]?.courseWorkload || c.hasCourseInstance?.courseWorkload),
  }));
  const site = { brand: topic, description: decode((index.match(/<meta name="description" content="([^"]*)"/) || [])[1] || "") };
  const h = { courses, guides: [], total: 0 };
  const T = text("en");
  const template = readFileSync(join(dir, "404.html"), "utf8");
  const image = (index.match(/<meta property="og:image" content="([^"]+)"/) || [])[1];
  const pages = [
    ["/about", T.aboutH1(topic), T.aboutDesc(topic), "AboutPage", site.description, T.aboutBody(site, h)],
    ["/contact", T.contactH1(topic), T.contactDesc(topic), "ContactPage", T.contactDesc(topic), T.contactBody(site)],
    ["/privacy", T.privacyH1, T.privacyDesc(topic), "WebPage", T.privacyDesc(topic), T.privacyBody(site, host)],
  ];
  const sitemap = [{ loc: `${base}/`, lastmod: dates.date(`${base}/`, index) }];
  for (const [path, h1, desc, type, lede, body] of pages) {
    const title = infoTitle(path.slice(1), h1, topic);
    const html = infoPage(template, { base, path, title, h1, description: fitDescription(desc), type, lede, body, topic, image });
    writeFileSync(join(dir, path.slice(1) + ".html"), html);
    sitemap.push({ loc: base + path, lastmod: dates.date(base + path, html) });
  }
  writeFileSync(join(dir, "sitemap.xml"), sitemapXml(sitemap));
  edit(join(dir, "llms.txt"), (s) => llms(s, base, topic, courses));
}

function edit(file, fn) {
  const before = readFileSync(file, "utf8");
  const after = fn(before);
  if (after !== before) writeFileSync(file, after);
  return after;
}

// The page's own gtag snippet (G-RVVCEBGVRX). The Worker injects the hub's Google Analytics and Clarity tags.
function noGa(s) {
  return s.replace(/<!-- Google tag \(gtag\.js\) -->\s*<script>[\s\S]*?G-RVVCEBGVRX[\s\S]*?<\/script>\n?/, "");
}

// Footer: local about, contact and privacy pages (the trust pages agents look for on the same site).
function footer(s) {
  return s
    .replace(`<li><a href="https://hazwoper-osha.com/privacy-policy">Privacy policy</a></li>`, `<li><a href="/privacy">Privacy</a></li>`)
    .replace(`<li><a href="https://hazwoper-osha.com/contact">Contact</a></li>`, `<li><a href="/about">About</a></li>\n        <li><a href="/contact">Contact</a></li>`);
}

function headHints(s, md) {
  if (!s.includes('name="is-agentic-site-type"')) {
    s = s.replace(`<meta name="robots" content="index, follow">`,
      `<meta name="robots" content="index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1">
<meta name="is-agentic-site-type" content="business">
<link rel="alternate" type="text/markdown" href="${md}">`);
  }
  if (!s.includes('<meta name="keywords"')) {
    // The product terms AI search should tie to the site: its course names, from the ItemList.
    const names = [...s.matchAll(/"@type":"Course","@id":"[^"]+","url":"[^"]+","name":"([^"]+)"/g)].map((m) => m[1]);
    if (names.length) s = s.replace(`<meta name="is-agentic-site-type" content="business">`,
      `<meta name="keywords" content="${esc([...new Set(names)].join(", "))}">\n<meta name="is-agentic-site-type" content="business">`);
  }
  return s;
}

// The company node gets the full record (address, contact point, logo, profiles); a WebSite node with
// the course names as keywords is added, so AI search can tie the brand to what it sells.
function enrichLd(s, base) {
  return s.replace(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/, (all, json) => {
    const data = JSON.parse(json);
    const graph = data["@graph"] || [];
    const ict = graph.find((n) => n["@id"] === "https://ictraining.us/#organization");
    if (ict && !ict.description) ict.description = "Industrial Certified Training, LLC, the parent company of HAZWOPER OSHA Training, LLC, which delivers these courses online.";
    const i = graph.findIndex((n) => n["@id"] === ORG_ID);
    if (i !== -1) graph[i] = { ...ORG, ...(graph[i].parentOrganization ? { parentOrganization: graph[i].parentOrganization } : {}) };
    const page = graph.find((n) => n["@type"] === "WebPage");
    const list = graph.find((n) => n["@type"] === "ItemList");
    if (!graph.some((n) => n["@type"] === "WebSite")) {
      graph.splice(2, 0, {
        "@type": "WebSite", "@id": `${base}/#website`, url: `${base}/`, name: page?.name, description: page?.description, inLanguage: "en-US",
        publisher: { "@id": ORG_ID }, keywords: (list?.itemListElement || []).map((e) => e.item?.name).filter(Boolean).join(", "),
      });
      if (page) page.isPartOf = { "@id": `${base}/#website` };
    }
    return `<script type="application/ld+json">${JSON.stringify(data).replace(/</g, "\\u003c")}</script>`;
  });
}

// An about/contact/privacy page in the site's own look: the 404 page's header and footer around new content.
function infoPage(template, { base, path, title, h1, description, type, lede, body, topic, image }) {
  const url = base + path;
  const graph = [ORG, { "@type": type, "@id": `${url}#webpage`, url, name: title, description, inLanguage: "en-US", publisher: { "@id": ORG_ID },
    isPartOf: { "@id": `${base}/#website` }, breadcrumb: { "@id": `${url}#breadcrumb` } },
  { "@type": "BreadcrumbList", "@id": `${url}#breadcrumb`, itemListElement: [
    { "@type": "ListItem", position: 1, name: topic, item: `${base}/` }, { "@type": "ListItem", position: 2, name: h1, item: url }] }];
  const head = `<title>${esc(title)}</title>
<meta name="description" content="${esc(description)}">
<link rel="canonical" href="${url}">
<meta name="robots" content="index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1">
<meta name="is-agentic-site-type" content="business">
<meta property="og:type" content="website">
<meta property="og:site_name" content="Industrial Certified Training">
<meta property="og:title" content="${esc(title)}">
<meta property="og:description" content="${esc(description)}">
<meta property="og:url" content="${url}">
<meta property="og:image" content="${image || ORG.logo}">
<meta name="twitter:card" content="summary_large_image">
<link rel="alternate" type="text/markdown" href="${path}.md">
<script type="application/ld+json">${JSON.stringify({ "@context": "https://schema.org", "@graph": graph }).replace(/</g, "\\u003c")}</script>`;
  return template
    .replace(/<title>[^<]*<\/title>\n<meta name="robots" content="noindex">/, head)
    .replace(/<main id="main" class="container section">[\s\S]*?<\/main>/,
      `<main id="main" class="container section info-page">
  <p class="eyebrow"><a href="/">${esc(topic)}</a></p>
  <h1>${esc(h1)}</h1>
  <p class="lede">${esc(lede)}</p>
${body.trim()}
</main>`);
}

function llms(s, base, topic, courses) {
  if (s.includes("## When to use this site")) return s;
  const when = `## When to use this site

- Use it when someone needs ${topic} and wants to compare the courses, prices and lengths, or enroll.
- Each course entry below lists the price per seat, the length, the regulation it follows and an enroll link that opens the checkout.
- For an invoice or purchase order, call ${PHONE} or email ${EMAIL}.
- Every page is also served as Markdown: send \`Accept: text/markdown\`, or add \`.md\` to the path (${base}/index.md).

`;
  const site = `
## Site

- [About](${base}/about)
- [Contact](${base}/contact)
- [Privacy](${base}/privacy)
- [Sitemap](${base}/sitemap.xml)
`;
  return s.replace("## Courses", when + "## Courses").trimEnd() + "\n" + site;
}

function hours(iso) {
  const m = String(iso || "").match(/PT(?:(\d+)H)?(?:(\d+)M)?/);
  if (!m) return "";
  const [h, min] = [Number(m[1] || 0), Number(m[2] || 0)];
  return h ? `${h} hour${h === 1 ? "" : "s"}${min ? ` ${min} min` : ""}` : `${min} min`;
}

function decode(s) {
  return String(s).replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#39;/g, "'");
}
